  /// < VC NOT supported
  static const int VC_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid state
  static const int VC_ERROR_INVALID_STATE = -49610735;

  /// < Invalid language
  static const int VC_ERROR_INVALID_LANGUAGE = -49610734;

  /// < No available engine
  static const int VC_ERROR_ENGINE_NOT_FOUND = -49610733;

  /// < Operation failed
  static const int VC_ERROR_OPERATION_FAILED = -49610732;

  /// < Operation rejected
  static const int VC_ERROR_OPERATION_REJECTED = -49610731;

  /// < List reached end
  static const int VC_ERROR_ITERATION_END = -49610730;

  /// < List empty
  static const int VC_ERROR_EMPTY = -49610729;

  /// < Service daemon reset (Since 3.0)
  static const int VC_ERROR_SERVICE_RESET = -49610728;

  /// < In progress to ready (Since 3.0)
  static const int VC_ERROR_IN_PROGRESS_TO_READY = -49610727;

  /// < In progress to recording (Since 3.0)
  static const int VC_ERROR_IN_PROGRESS_TO_RECORDING = -49610720;

  /// < In progress to processing (Since 3.0)
  static const int VC_ERROR_IN_PROGRESS_TO_PROCESSING = -49610719;

  /// < Not supported feature of current engine (Since 4.0)
  static const int VC_ERROR_NOT_SUPPORTED_FEATURE = -49610718;

  /// < TTS operation failed (Since 7.0)
